import{_ as n,a as i,b as r,c as o}from"./chunks/settings.E85cD48m.js";import{_ as l,C as c,o as p,c as h,a2 as m,E as t,j as s,a as d}from"./chunks/framework.CFuv5BrO.js";const C=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Hearth OS","text":"把数字劳动变成可靠的任务","tagline":"单用户、自托管、长期驻留的个人 Agent OS。聊天优先地发起任务，交给三个内置执行器，在审批、操作账本与回执约束下完成真实工作。","image":{"src":"/hero.svg","alt":"Hearth OS 任务系统"},"actions":[{"theme":"brand","text":"阅读设计说明","link":"/design/"},{"theme":"alt","text":"查看交付路线","link":"/delivery/"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1795426969000}'),_={name:"index.md"};function u(g,e,f,k,x,b){const a=c("DocCardGrid");return p(),h("div",null,[e[0]||(e[0]=m('<nav class="home-quicklinks" aria-label="文档入口"><a href="#产品界面"><span class="home-quicklinks__label">产品界面</span><span class="home-quicklinks__meta">聊天、资料库、Context 与执行器</span></a><a href="/hearth-os/architecture/"><span class="home-quicklinks__label">代码架构</span><span class="home-quicklinks__meta">服务组装、运行时账本、沙箱与前端</span></a><a href="/hearth-os/delivery/"><span class="home-quicklinks__label">交付路线</span><span class="home-quicklinks__meta">从 MVP 到 v1.0 的分阶段计划</span></a><a href="/hearth-os/evaluation/"><span class="home-quicklinks__label">评测与结果</span><span class="home-quicklinks__meta">Native 30 题报告、复现方式与评测边界</span></a><a href="/hearth-os/log/day-08.html"><span class="home-quicklinks__label">开发日志</span><span class="home-quicklinks__meta">通用执行内核、评测升级与每日提交</span></a></nav><h2 id="产品界面" tabindex="-1">产品界面 <a class="header-anchor" href="#产品界面" aria-label="Permalink to &quot;产品界面&quot;">​</a></h2><p class="home-section-lead"> 不是把聊天记录换个皮肤，而是把一次真实工作拆成可追踪的任务：目标、执行器、权限、审批、产物、结算与回执，全部留在同一个控制面里。 </p><section class="home-showcase" aria-label="Hearth 界面截图"><figure class="screenshot-spotlight"><img src="'+n+'" alt="Hearth 聊天工作台"><figcaption><strong>聊天工作台</strong><span>执行轨迹内联在对话时间线；右侧“对话产物”按需展开文件、后台任务和预览。</span></figcaption></figure><div class="screenshot-gallery"><figure class="screenshot-card"><img src="'+i+'" alt="资料库"><figcaption><strong>资料库</strong><span>文件、记忆、资料与技能在一个树里；检索、预览和回收站同页完成。</span></figcaption></figure><figure class="screenshot-card"><img src="'+r+'" alt="Context 交接"><figcaption><strong>Context 交接</strong><span>从活跃记忆生成接手摘要、原记录与导出包，交给下一个执行者或账号。</span></figcaption></figure><figure class="screenshot-card screenshot-card--wide"><img src="'+o+'" alt="设置与执行器"><figcaption><strong>设置与执行器</strong><span>左侧只做分区；执行器健康、模型绑定、浏览器、扩展和数据页都在右侧一栏。</span></figcaption></figure></div></section><h2 id="产品定位" tabindex="-1">产品定位 <a class="header-anchor" href="#产品定位" aria-label="Permalink to &quot;产品定位&quot;">​</a></h2><p>Hearth 不是另一个聊天壳，也不是只服务于代码的 Agent。它是一个<strong>以任务为中心的个人控制面</strong>：用户提出意图，系统保存目标、分配执行器、约束权限、记录证据，并在外部动作发生前要求明确审批。</p>',6)),t(a,{columns:3,items:[{no:"01",title:"任务优先，而不是消息优先",text:"每次执行都有预算、检查点、恢复路径和产物记录。失败可以重试，结果落盘后才算完成。",link:"/design/tasks",meta:"Durable execution"},{no:"02",title:"外部动作先审批，再留下回执",text:"发送邮件、操作桌面、提交页面等副作用先生成预览，一次性审批绑定参数指纹与操作账本。",link:"/design/effects",meta:"Approval & effects"},{no:"03",title:"崩溃后可恢复，完成有证据",text:"HostKernel 阶段化恢复、未结算操作不重放、终态 run 输出 run-evidence；沙箱限制文件、进程与网络。",link:"/architecture/runtime-operations",meta:"Recovery & evidence"}]}),e[1]||(e[1]=s("h2",{id:"从这里开始",tabindex:"-1"},[d("从这里开始 "),s("a",{class:"header-anchor",href:"#从这里开始","aria-label":'Permalink to "从这里开始"'},"​")],-1)),t(a,{columns:2,items:[{title:"交付与进度",text:"第一阶段 MVP 已验收；0.3.4 把运行时、沙箱与恢复链收紧成可核对的闭环，真实用户与长期运行验收仍在进行。",link:"/delivery/status",meta:"Current status"},{title:"存储与备份边界",text:"SQLite 单一事件日志、操作账本、上下文生命周期、加密备份，以及数据库可恢复不等于产物可迁移的边界。",link:"/design/storage",meta:"Data & backup"},{title:"运行时账本与宿主生命周期",text:"T1/T2 操作合同、HostKernel 租约、单一事件日志、AppContainer、ConPTY 与持久后台进程。",link:"/architecture/runtime-operations",meta:"Runtime operations"},{title:"Native Harness 沙箱",text:"Windows AppContainer 的文件、进程与网络边界，fail-closed 规则，以及它明确不承诺的部分。",link:"/design/sandbox",meta:"Sandbox boundary"}]})])}const P=l(_,[["render",u]]);export{C as __pageData,P as default};
